<script lang="ts">
 import {onDestroy} from 'svelte';import {companion,updateData} from '../state.svelte';import {interfaceState} from '../interfaceState.svelte';import {brightnessValue} from '../islandTime';import SloshGauge from './SloshGauge.svelte';
 let current=$derived(brightnessValue(interfaceState.brightnessPreview??companion.data.preferences.brightness));
 function save(value:number){const next=brightnessValue(value);if(next!==brightnessValue(companion.data.preferences.brightness))updateData(data=>data.preferences.brightness=next);interfaceState.brightnessPreview=null;}
 onDestroy(()=>interfaceState.brightnessPreview=null);
</script>
<div class="brightness-content"><h3>页面亮度</h3><p>拖动光瓶，找到舒服的亮度。</p><div class="brightness-editor"><SloshGauge value={current} reduced={companion.data.preferences.reduceMotion} oninput={value=>interfaceState.brightnessPreview=value} oncommit={save}/><div class="brightness-options">{#each [{value:40,label:'微光'},{value:70,label:'柔和'},{value:100,label:'明亮'}] as option}<button type="button" class:chosen={current===option.value} aria-pressed={current===option.value} onclick={()=>save(option.value)}>{option.label}<span>{option.value}%</span></button>{/each}</div></div><button type="button" class="text-button brightness-reset" onclick={()=>save(100)}>恢复100%</button><small>整体页面亮度 40%–100%；55% 及以下自动进入夜间，调亮后恢复所选模式。</small></div>
<style>.brightness-content{width:100%;color:var(--xy-ink)}h3{font-size:16px;margin:0 0 6px;font-weight:600}.brightness-content p{font-size:12px!important;color:var(--xy-secondary);line-height:1.7;margin-bottom:14px}.brightness-editor{display:flex;align-items:center;gap:20px}.brightness-options{display:grid;gap:7px;flex:1}.brightness-options button{display:flex;justify-content:space-between;align-items:center;width:100%;min-height:40px;border:1px solid var(--xy-border);background:var(--xy-panel);color:var(--xy-ink);padding:7px 11px;border-radius:6px;font-size:14px}.brightness-options button span{font-size:12px;color:var(--xy-secondary);font-variant-numeric:tabular-nums}.brightness-options .chosen{background:var(--xy-selected);border-color:var(--xy-accent);font-weight:600}.brightness-reset{display:block;margin-top:10px;padding:6px 0;text-decoration:underline;text-underline-offset:3px}.brightness-content small{display:block;font-size:12px;line-height:1.7;color:var(--xy-secondary)}@media(max-width:1000px){.brightness-options button{min-height:44px}}</style>
